// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 ts, address actor) public {
        ts = bound(ts, 1, type(uint48).max);
        vm.assume(actor != address(0) && actor != address(c));

        vm.warp(ts);
        vm.deal(actor, 20 ether);

        // first call at timestamp ts succeeds (ts > pastBlockTime == 0)
        vm.prank(actor);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        assertTrue(ok1, "first call should succeed");

        // second call in the SAME block: timestamp equals pastBlockTime now,
        // so reference C must revert (strict >), mutant M succeeds (>=)
        vm.prank(actor);
        (bool ok2,) = address(c).call{value: 10 ether}("");

        assertTrue(!ok2, "second same-block call must revert");
    }
}
